import argparseimport loggingimport sysfrom src.config import PROJECT_ROOT, DB, SETTINGSfrom src.common.audit import new_run_idfrom src.common.errors import PipelineStageErrorlog = logging.getLogger('pipeline')# ---- Added: thin handlers. Each one only calls into a module. ----def cmd_extract(args, run_id):    from src.extract.files import extract_sources  # lab-specified signature: extract_sources(run_id)    extract_sources(run_id)def cmd_transform(args, run_id):    from src.config import path_for    from src.transform.staging import build_staging    from src.transform.curated import build_curated    raw_dir = path_for('raw_dir') / f'run_id={run_id}'  # snapshot written by extract    staging, _ = build_staging(raw_dir, run_id)    build_curated(staging, run_id)def cmd_load(args, run_id):    import pandas as pd    from src.config import path_for    from src.load.postgres import upsert_curated    curated_path = path_for('curated_dir') / f'run_id={run_id}' / 'sales_order_lines.parquet'    if not curated_path.exists():        raise FileNotFoundError(            f'Curated data not found: {curated_path}. Run transform with the same '            f'run id first (or use run-all).'        )    curated = pd.read_parquet(curated_path)    written = upsert_curated(curated, run_id)    log.info('load run_id=%s: %d row(s) written', run_id, written)def cmd_validate(args, run_id):    import pandas as pd    from src.config import path_for    from src.validate.quality import validate_curated    curated_path = path_for('curated_dir') / f'run_id={run_id}' / 'sales_order_lines.parquet'    curated = pd.read_parquet(curated_path)    errors = validate_curated(curated)    if errors:        for e in errors:            log.error('validation failed: %s', e)        raise ValueError(f'{len(errors)} validation error(s); see log above')    log.info('validate run_id=%s: %d row(s) passed all checks', run_id, len(curated))def cmd_benchmark(args, run_id):    from src.config import path_for    from src.benchmark.storage import run_benchmark    curated_path = path_for('curated_dir') / f'run_id={run_id}' / 'sales_order_lines.parquet'    if not curated_path.exists():        raise FileNotFoundError(            f'Curated data not found: {curated_path}. Run transform (same --run-id) first.'        )    results = run_benchmark(curated_path, path_for('benchmark_dir'), repeats=args.repeats)    log.info('benchmark run_id=%s:\n%s', run_id, results.to_string(index=False))def cmd_load_partition(args, run_id):    import pandas as pd    from src.config import path_for    from src.benchmark.storage import read_partition, write_partitioned_parquet    from src.load.postgres import load_partition    # Rebuild the partitioned tree from THIS run's curated data every time, not only    # when missing. data/partitioned/ is not run-scoped (see src.benchmark.storage),    # so a scheduled run must refresh it or a later load-partition would silently    # read a stale snapshot from a previous day's curated output.    partition_dir = path_for('partition_dir')    curated_path = path_for('curated_dir') / f'run_id={run_id}' / 'sales_order_lines.parquet'    if not curated_path.exists():        raise FileNotFoundError(            f'Curated data not found: {curated_path}. Run transform with the same '            f'run id first (or use run-all).'        )    write_partitioned_parquet(pd.read_parquet(curated_path), partition_dir)    df = read_partition(partition_dir, args.year, args.month)    written = load_partition(df, args.year, args.month, run_id)    log.info('load-partition %04d-%02d run_id=%s: %d row(s) written',              args.year, args.month, run_id, written)def cmd_run_all(args, run_id):    # run-all = extract -> transform under ONE run_id; load/validate stay separate commands.    _run_stage('extract', cmd_extract, args, run_id)    _run_stage('transform', cmd_transform, args, run_id)COMMANDS = {    'extract': cmd_extract,    'transform': cmd_transform,    'load': cmd_load,    'validate': cmd_validate,    'benchmark': cmd_benchmark,    'load-partition': cmd_load_partition,    'run-all': cmd_run_all,}def _run_stage(stage, handler, args, run_id):    """Run a stage; wrap any failure with stage + run_id context (never swallow it)."""    log.info('stage=%s run_id=%s started', stage, run_id)    try:        handler(args, run_id)    except PipelineStageError:        raise    except Exception as exc:  # re-raised with context, so nothing is silenced        raise PipelineStageError(stage, run_id, exc) from exc    log.info('stage=%s run_id=%s finished', stage, run_id)# ---- End of added helpers ----def main():    parser = argparse.ArgumentParser(description='DSS150P modular pipeline')    sub = parser.add_subparsers(dest='command', required=True)    sub.add_parser('validate-env')    sub.add_parser('extract')    sub.add_parser('transform')    sub.add_parser('load')    sub.add_parser('validate')    b = sub.add_parser('benchmark'); b.add_argument('--repeats', type=int, default=5)    p = sub.add_parser('load-partition'); p.add_argument('--year', type=int, required=True); p.add_argument('--month', type=int, required=True)    sub.add_parser('run-all')    # Added: optional --run-id so Airflow can pass one ID to every task (Goal 4).    # Purely additive: commands behave exactly as before when it is omitted.    for name in ('extract', 'transform', 'load', 'validate', 'benchmark', 'load-partition', 'run-all'):        sub.choices[name].add_argument('--run-id', default=None)    args = parser.parse_args()    if args.command == 'validate-env':        print('PROJECT_ROOT=', PROJECT_ROOT)        print('DB host/database=', DB['host'], DB['dbname'])        print('Configured source=', SETTINGS['pipeline']['source_dir'])        return    # Wire the modular functions together. Keep orchestration logic thin.    logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(name)s %(message)s')    if args.command == 'load-partition' and not 1 <= args.month <= 12:        parser.error('--month must be between 1 and 12')    run_id = getattr(args, 'run_id', None) or new_run_id()    try:        _run_stage(args.command, COMMANDS[args.command], args, run_id)    except PipelineStageError as err:        log.error('%s', err, exc_info=err.cause)        sys.exit(1)  # non-zero exit code so Airflow marks the task as failedif __name__ == '__main__':    main()